function check([operations, args], actual, expected) {
  const rects = args[0][0];
  if (!Array.isArray(actual) || actual.length !== operations.length || actual[0] !== null) return false;
  const sizes = rects.map(([a, b, x, y]) => (x - a + 1) * (y - b + 1));
  const total = sizes.reduce((sum, s) => sum + s, 0);
  const hits = rects.map(() => []);
  for (let i = 1; i < actual.length; i++) {
    const point = actual[i];
    if (!Array.isArray(point) || point.length !== 2 || !Number.isInteger(point[0]) || !Number.isInteger(point[1])) return false;
    const [u, v] = point;
    const r = rects.findIndex(([a, b, x, y]) => a <= u && u <= x && b <= v && v <= y);
    if (r === -1) return false;
    hits[r].push([u - rects[r][0], v - rects[r][1]]);
  }
  const calls = actual.length - 1;
  // A count of a fair choice with probability p over n tries stays within 5.5 standard deviations (+3 slack).
  const fair = (seen, n, p) => Math.abs(seen - n * p) <= 5.5 * Math.sqrt(n * p * (1 - p)) + 3;
  // Each rectangle gets about its share of the points; a chi-square over the well-filled rectangles adds power.
  let chi = 0, cells = 0;
  for (let r = 0; r < rects.length; r++) {
    const p = sizes[r] / total, mean = calls * p;
    if (!fair(hits[r].length, calls, p)) return false;
    if (mean >= 5) { chi += (hits[r].length - mean) ** 2 / mean; cells++; }
  }
  if (cells > 1 && chi > cells + 6 * Math.sqrt(2 * cells) + 8) return false;
  // Inside a rectangle with enough hits: every point of a small one, each row and column of a narrow side,
  // and the average offset of a wide side must look uniform.
  for (let r = 0; r < rects.length; r++) {
    const seen = hits[r].length;
    if (seen < 30) continue;
    const width = rects[r][2] - rects[r][0] + 1, height = rects[r][3] - rects[r][1] + 1;
    if (width * height <= 25) {
      const grid = new Map();
      for (const [du, dv] of hits[r]) grid.set(du * height + dv, (grid.get(du * height + dv) || 0) + 1);
      for (let cell = 0; cell < width * height; cell++) if (!fair(grid.get(cell) || 0, seen, 1 / (width * height))) return false;
    }
    for (const [axis, span] of [[0, width], [1, height]]) {
      if (span <= 10) {
        for (let k = 0; k < span; k++) if (!fair(hits[r].filter(h => h[axis] === k).length, seen, 1 / span)) return false;
      } else {
        const average = hits[r].reduce((sum, h) => sum + h[axis] / (span - 1), 0) / seen;
        if (Math.abs(average - 0.5) > 6 * Math.sqrt(0.11 / seen) + 0.02) return false;
      }
    }
  }
  return true;
}

