function validate([operations, args]) {
  const rects = args[0][0];
  if (rects.length < 1 || rects.length > 100) return 'rects needs 1 to 100 rectangles.';
  for (const rect of rects) {
    if (rect.length !== 4) return 'Each rectangle is [a, b, x, y].';
    const [a, b, x, y] = rect;
    if ([a, b, x, y].some(c => c < -1e9 || c > 1e9)) return 'Coordinates are between -10^9 and 10^9.';
    if (a >= x || b >= y) return 'Each rectangle needs a < x and b < y.';
    if (x - a > 2000 || y - b > 2000) return 'Each side is at most 2000 long.';
  }
  for (let i = 0; i < rects.length; i++)
    for (let j = i + 1; j < rects.length; j++) {
      const [a1, b1, x1, y1] = rects[i], [a2, b2, x2, y2] = rects[j];
      if (a1 <= x2 && a2 <= x1 && b1 <= y2 && b2 <= y1) return 'Rectangles must not overlap or touch.';
    }
  if (operations.slice(1).some(op => op !== 'pick')) return 'After the constructor, only pick is called.';
  return null;
}

