class Solution {
  constructor(rects) {
    this.rects = rects;
    this.prefix = [];
    let total = 0;
    for (const [a, b, x, y] of rects) {
      total += (x - a + 1) * (y - b + 1);
      this.prefix.push(total);
    }
    this.total = total;
  }

  pick() {
    const target = Math.floor(Math.random() * this.total);
    let left = 0;
    let right = this.prefix.length - 1;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (this.prefix[mid] > target) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }
    const [a, b, x] = this.rects[left];
    const offset = target - (left === 0 ? 0 : this.prefix[left - 1]);
    const width = x - a + 1;
    return [a + (offset % width), b + Math.floor(offset / width)];
  }
}

