class Solution {
  constructor(rects) {
    this.rects = rects;
    this.counts = rects.map(([a, b, x, y]) => (x - a + 1) * (y - b + 1));
  }
  pick() {
    // Walk the rectangles with a weighted roll, then draw each coordinate on its own.
    let roll = Math.random() * this.counts.reduce((s, c) => s + c, 0);
    let i = 0;
    while (i < this.counts.length - 1 && roll >= this.counts[i]) roll -= this.counts[i++];
    const [a, b, x, y] = this.rects[i];
    return [a + Math.floor(Math.random() * (x - a + 1)), b + Math.floor(Math.random() * (y - b + 1))];
  }
}

