function generate(rand, size) {
  const large = size === 'large';
  const count = large ? 100 : 1 + Math.floor(rand() * 4);
  const maxSide = large ? 2000 : 1 + Math.floor(rand() * 4);
  const far = !large && rand() < 0.2;
  const rects = [];
  // Rectangles go left to right with a gap of at least one unit, so none share a point.
  let start = far ? 1e9 - 30 - 4 * maxSide : Math.floor(rand() * 21) - 10;
  if (far && rand() < 0.5) start = -1e9;
  for (let i = 0; i < count; i++) {
    const width = 1 + Math.floor(rand() * maxSide), height = 1 + Math.floor(rand() * maxSide);
    const b = large ? Math.floor(rand() * (2e9 - 2000)) - 1e9 : Math.floor(rand() * 7) - 3;
    rects.push([start, b, start + width, b + height]);
    start += width + 1 + Math.floor(rand() * (large ? 1000000 : 3));
  }
  const calls = large ? 499 : 1 + Math.floor(rand() * 300);
  return [["Solution", ...Array(calls).fill("pick")], [[rects], ...Array.from({ length: calls }, () => [])]];
}
